.darma-loader-darma-b17-jackhammer { --accent: var(--loader-color, #f59e0b); --accent-2: var(--loader-secondary-color, #475569); width: var(--loader-size, 112px); height: var(--loader-size, 112px); position: relative; }
.darma-loader-darma-b17-jackhammer .darma-loader-darma-b17-jackhammer__rig { position: absolute; left: 33%; top: 4%; width: 34%; height: 74%; animation: darma-loader-darma-b17-jackhammer-jack-buck calc(var(--loader-speed, 1s) * .22) ease-in-out infinite; }
.darma-loader-darma-b17-jackhammer .darma-loader-darma-b17-jackhammer__grip { position: absolute; left: -18%; top: 0; width: 136%; height: 12%; border-radius: 5px; background: var(--accent-2); }
.darma-loader-darma-b17-jackhammer .darma-loader-darma-b17-jackhammer__barrel { position: absolute; left: 16%; top: 10%; width: 68%; height: 62%; border-radius: 6px; background: linear-gradient(90deg, var(--accent), color-mix(in srgb, #000 22%, var(--accent))); }
.darma-loader-darma-b17-jackhammer .darma-loader-darma-b17-jackhammer__bit { position: absolute; left: 38%; top: 70%; width: 24%; height: 32%; border-radius: 2px; background: linear-gradient(#cbd5e1, #64748b); }
.darma-loader-darma-b17-jackhammer .darma-loader-darma-b17-jackhammer__slab { position: absolute; left: 6%; right: 6%; bottom: 4%; height: 16%; border-radius: 4px; background: repeating-linear-gradient(90deg, var(--accent-2) 0 18%, color-mix(in srgb, #000 18%, var(--accent-2)) 0 20%); animation: darma-loader-darma-b17-jackhammer-jack-shake calc(var(--loader-speed, 1s) * .22) ease-in-out infinite; }
.darma-loader-darma-b17-jackhammer i { position: absolute; bottom: 18%; width: 7%; height: 6%; border-radius: 2px; background: var(--accent-2); opacity: 0; animation: darma-loader-darma-b17-jackhammer-jack-chip calc(var(--loader-speed, 1s) * .88) ease-out infinite; }
.darma-loader-darma-b17-jackhammer i:nth-of-type(1) { left: 30%; --dx: -150%; }
.darma-loader-darma-b17-jackhammer i:nth-of-type(2) { left: 47%; --dx: 20%; animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b17-jackhammer i:nth-of-type(3) { left: 62%; --dx: 160%; animation-delay: calc(var(--loader-speed, 1s) * .6); }
@keyframes darma-loader-darma-b17-jackhammer-jack-buck { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(5%); } }
@keyframes darma-loader-darma-b17-jackhammer-jack-shake { 0%, 100% { transform: translateX(0); } 50% { transform: translateX(1.5%); } }
@keyframes darma-loader-darma-b17-jackhammer-jack-chip { 0% { opacity: 0; transform: translate(0, 0) rotate(0deg); } 15% { opacity: 1; } 100% { opacity: 0; transform: translate(var(--dx, 0%), -180%) rotate(200deg); } }

